const out = [];
for (const item of $input.all()) {
  const body = item.json.body || item.json || {};
  const description = body.description || body.message || body.text || '';
  // A request with no description used to produce zero items, so no Respond node ran and
  // the caller hung. Mark it instead and acknowledge it below.
  if (!description) { out.push({ json: { skip: true, reason: 'missing_description' } }); continue; }
  out.push({ json: {
    business_id: body.business_id || 'default',
    owner_phone: String(body.owner_phone || '923000000000').replace(/\D/g, ''),
    customer_name: body.customer_name || body.name || '',
    customer_phone: String(body.customer_phone || body.phone || '').replace(/\D/g, ''),
    phone_number_id: body.phone_number_id || 'YOUR_PHONE_NUMBER_ID',
    service_type: body.service_type || 'unknown',
    description,
    photos: Array.isArray(body.photos) ? body.photos : [],
    pricing_rules: body.pricing_rules || {},
    idempotency_key: body.idempotency_key || ('quote-' + Date.now()),
    received_at: new Date().toISOString()
  }});
}
return out;

const source = $('Normalize Quote Request').item.json;
let ai = {};
try { ai = JSON.parse($input.first().json.choices?.[0]?.message?.content || '{}'); } catch (e) { ai = {}; }
const quoteNo = 'Q-' + new Date().toISOString().slice(0,10).replace(/-/g,'') + '-' + Math.floor(1000 + Math.random()*9000);
const questions = Array.isArray(ai.missing_questions) ? ai.missing_questions.slice(0,2) : [];
const items = Array.isArray(ai.suggested_items) ? ai.suggested_items : [];
const needsInfo = questions.length > 0 || ai.site_visit_required === true || ai.recommended_quote_mode === 'inspection_first';
const customerReply = ai.customer_reply || (needsInfo ? 'Please share a little more detail so we can prepare a proper quote.' : 'Thanks. We are preparing your quote and will share it shortly.');
const ownerMessage = `Quote approval needed: ${quoteNo}\nCustomer: ${source.customer_name || source.customer_phone}\nService: ${ai.service_type || source.service_type}\nRisk: ${ai.risk_level || 'medium'}\nSummary: ${ai.problem_summary || source.description}\nMode: ${ai.recommended_quote_mode || 'range'}\nSuggested items: ${JSON.stringify(items)}`;
return [{ json: {
  business_id: source.business_id,
  quote_no: quoteNo,
  idempotency_key: source.idempotency_key,
  customer_name: source.customer_name,
  customer_phone: source.customer_phone,
  phone_number_id: source.phone_number_id,
  owner_phone: source.owner_phone,
  service_type: ai.service_type || source.service_type,
  problem_summary: ai.problem_summary || source.description,
  risk_level: ai.risk_level || 'medium',
  quote_mode: ai.recommended_quote_mode || 'range',
  site_visit_required: ai.site_visit_required === true ? 'yes' : 'no',
  missing_questions: JSON.stringify(questions),
  suggested_items: JSON.stringify(items),
  customer_reply: customerReply,
  owner_message: ownerMessage,
  route: needsInfo ? 'needs_info' : 'owner_approval',
  status: needsInfo ? 'needs_info' : 'draft_ready',
  created_at: new Date().toISOString()
}}];
